import{_ as t,o as r,c as i,a4 as a}from"./chunks/framework.BybBnFXO.js";const u=JSON.parse('{"title":"Same-Colour Gems","description":"","frontmatter":{"title":"Same-Colour Gems","identification":"same-color-gems"},"headers":[],"relativePath":"identification/same-color-gems.md","filePath":"identification/same-color-gems.md","lastUpdated":1785884429000}'),o={name:"identification/same-color-gems.md"};function s(n,e,l,d,c,m){return r(),i("div",null,[...e[0]||(e[0]=[a(`<h1 id="same-colour-gems" tabindex="-1">Same-Colour Gems <a class="header-anchor" href="#same-colour-gems" aria-label="Permalink to &quot;Same-Colour Gems&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>One colour can hide many species — red may be ruby, spinel, garnet, or glass. Combining RI / SG / pleochroism / inclusions eliminates candidates one by one. The trees below cover the three most confusing families: red, blue, and green.</p><h2 id="decision-tree" tabindex="-1">Decision Tree <a class="header-anchor" href="#decision-tree" aria-label="Permalink to &quot;Decision Tree&quot;">​</a></h2><div><pre class="mermaid">flowchart TD
  A[Red stone] --&gt; B{Refractive index}
  B --&gt;|1.76| C[Corundum]
  C --&gt; D{UV fluorescence}
  D --&gt;|strong red| E[Ruby]
  D --&gt;|weak| F[needs spectrum]
  B --&gt;|1.71-1.72| G[Spinel]
  B --&gt;|1.74-1.89| H[Garnet]
  B --&gt;|1.5-1.7 glassy| I{bubbles / swirls?}
  I --&gt;|yes| J[Glass imitation]
  I --&gt;|no| K[re-check refractometer]
</pre></div><h2 id="core-principles" tabindex="-1">Core Principles <a class="header-anchor" href="#core-principles" aria-label="Permalink to &quot;Core Principles&quot;">​</a></h2><ul><li>Red: ruby RI 1.76 + strong red fluor.; spinel 1.71–1.72 none; garnet 1.74–1.89.</li><li>Blue: sapphire 1.76 dichroic blue/green; tanzanite 1.69–1.70 strongly trichroic; iolite 1.54 trichroism extreme.</li><li>Green: emerald 1.57–1.58 (oiled fissures); tsavorite 1.89 high dispersion; peridot 1.65–1.69 (doubling).</li><li>Fluorescence is the fast screen: natural ruby strong LW red; flame-fusion synthetic often stronger and whitish.</li></ul><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to &quot;Examples&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Gem</th><th>Value</th><th>Note</th></tr></thead><tbody><tr><td>ruby</td><td>RI 1.76 + red fluor.</td><td>vs spinel 1.72</td></tr><tr><td>sapphire</td><td>RI 1.76, no pleochroism</td><td>vs tanzanite 1.69 trichroic</td></tr><tr><td>emerald</td><td>RI 1.57 + oil fissures</td><td>vs tsavorite 1.89</td></tr></tbody></table><p><em>See the <a href="./intro.html">identification overview</a>.</em></p>`,10)])])}const p=t(o,[["render",s]]);export{u as __pageData,p as default};
